package com.alan.clients.module.impl.movement.flight;

import com.alan.clients.event.Listener;
import com.alan.clients.event.annotations.EventLink;
import com.alan.clients.event.impl.motion.PreMotionEvent;
import com.alan.clients.event.impl.packet.PacketReceiveEvent;
import com.alan.clients.module.impl.movement.Flight;
import com.alan.clients.util.packet.PacketUtil;
import com.alan.clients.util.player.MoveUtil;
import com.alan.clients.value.Mode;
import net.minecraft.network.Packet;
import net.minecraft.network.play.client.C03PacketPlayer;
import net.minecraft.network.play.server.S08PacketPlayerPosLook;
import net.minecraft.network.play.server.S12PacketEntityVelocity;
import net.minecraft.util.MathHelper;

public class MineLandFlight extends Mode<Flight> {

    private double serverPosX, serverPosY, serverPosZ;
    private boolean teleported;

    public MineLandFlight(String name, Flight parent) {
        super(name, parent);
    }

    @Override
    public void onEnable() {
        serverPosX = mc.thePlayer.posX;
        serverPosY = mc.thePlayer.posY;
        serverPosZ = mc.thePlayer.posZ;
        teleported = false;
    }

    @EventLink
    public final Listener<PreMotionEvent> onPreMotionEvent = event -> {
        if (!teleported) {

            final double yaw = MoveUtil.direction();
            final double speed = 6;

            if (mc.thePlayer.ticksExisted % 3 == 0) {
                PacketUtil.send(new C03PacketPlayer(mc.thePlayer.onGround));
                mc.thePlayer.setPosition(serverPosX, serverPosY, serverPosZ);
            }

            event.setPosY(event.getPosY() - 1.1 + (mc.thePlayer.ticksExisted % 3 == 0 ? 0.42f : 0));
            event.setPosX(event.getPosX() + MathHelper.sin((float) yaw) * speed);
            event.setPosZ(event.getPosZ() - MathHelper.cos((float) yaw) * speed);

        } else {
            mc.timer.timerSpeed = 0.3f;
        }
    };

    @EventLink
    public final Listener<PacketReceiveEvent> onPacketReceiveEvent = event -> {
        final Packet<?> packet = event.getPacket();

        if (packet instanceof S08PacketPlayerPosLook && !teleported) {
            event.setCancelled();
        } else if (packet instanceof S12PacketEntityVelocity) {
            final S12PacketEntityVelocity wrapper = (S12PacketEntityVelocity) packet;

            if (wrapper.getEntityID() == mc.thePlayer.getEntityId() && wrapper.motionY / 8000D > 0.5) {
                teleported = true;
            }
        }
    };
}
// NOTE (AI): Mode of the Rise 6.x Flight module tuned for the MineLand server family. The S08 handler cancels every teleport while teleported is false, so the spoofed position stream from PreMotion (posY dropped 1.1, 6 blocks per tick forward) is never snapped back. The teleport is only accepted once the server confirms the fall through an S12 velocity packet with motionY / 8000D > 0.5, after which timerSpeed drops to 0.3. This cancel-then-accept pattern is the canonical S08 ground-spoof: cancel rubberbands while airborne, let the teleport through the moment the server has committed to the new position. The C03 broadcast every 3 ticks with setPosition back to serverPos pins the server-side bounding box at the launch point.

