                if (downY > 2.5) {
                    downY = 0;
                    mc.getNetHandler().addToSendQueue(new C03PacketPlayer.C04PacketPlayerPosition(vec3.getX(),
                            vec3.getY(), vec3.getZ(), true));
                } else {
                    mc.getNetHandler().addToSendQueue(new C03PacketPlayer.C04PacketPlayerPosition(vec3.getX(),
                            vec3.getY(), vec3.getZ(), false));
                }
                lastY = vec3.getY();
            }
            //Teleported
            mc.thePlayer.setPosition(x, y, z);
            this.setState(false);
        }
    }


